def check_n(n):
    # Find all possible m in {1, ..., n-1}
    # such that x^m * (x^(n-m) - 1) is zero mod n for all x.
    # This is equivalent to:
    # 1. m >= v_p(n) for all p|n
    # 2. n-m is a multiple of lambda(n)
    # where v_p(n) is the exponent of p in the prime factorization of n.
    # lambda(n) is the Carmichael function.

    import math
    from sympy import totient, lambda_phi, primefactors, factorint

    def get_max_v_p(n):
        factors = factorint(n)
        return max(factors.values())

    def get_lambda(n):
        from sympy.ntheory import lambda_phi
        return lambda_phi(n)

    M = get_max_v_p(n)
    L = get_lambda(n)

    possible_m = []
    for m in range(M, n):
        if (n - m) % L == 0:
            possible_m.append(m)

    # Verify one of them
    if possible_m:
        m = possible_m[0]
        # P(x) = x^n - x^m
        # Check P(k) % n == 0 for k in 1..n
        for k in range(1, n + 1):
            if (k**n - k**m) % n != 0:
                return False, m
        return True, m
    else:
        return False, None

results = []
for n in range(2, 15):
    res, m = check_n(n)
    results.append((n, res, m))
print(results)

