def check_n(n):
    def get_max_v_p(n):
        factors = {}
        d = 2
        temp_n = n
        while d * d <= temp_n:
            while temp_n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp_n //= d
            d += 1
        if temp_n > 1:
            factors[temp_n] = factors.get(temp_n, 0) + 1
        return max(factors.values())

    M = get_max_v_p(n)
    L = get_lambda(n)

    possible_m = []
    for m in range(M, n):
        if (n - m) % L == 0:
            possible_m.append(m)

    if possible_m:
        m = possible_m[0]
        # P(x) = x^n - x^m
        # Check P(k) % n == 0 for k in 1..n
        # Using pow for large numbers
        for k in range(1, n + 1):
            if (pow(k, n, n) - pow(k, m, n)) % n != 0:
                return False, m
        return True, m
    else:
        return False, None

